async function connect() {
    setNotice('');
    const before = derived.length;
    const updated = await updateGame('connect-evidence', { sources: selected });
    if (updated) {
      setSelected([]);
      setNotice(
        Object.keys(updated.derivedEvidence).length > before
          ? '새 추론 증거를 확보했습니다.'
          : '이미 확보한 연결입니다. 같은 추론 증거를 중복 생성하지 않았습니다.',
      );
    }
  }

