export function NotesScreen({
  state,
  notes,
  setNotes,
  noteStatus,
  busy,
  updateGame,
  setNoteStatus,
}: Props) {
  return (
    <>
      <div className="desk-heading">
        <div className="eyebrow">DETECTIVE’S NOTEBOOK</div>
        <h1>
          수사 노트<span>.</span>
        </h1>
        <p>사소한 의심도 기록하세요. 다음 단서가 될 수 있습니다.</p>
      </div>
      <div className="notebook">
        <div className="notebook-top">
          <span>
            <StickyNote size={16} /> CASE #0001 · 개인 기록
          </span>
          <div className="notebook-emblem" aria-hidden="true">
            <span>❧</span>
            <Search size={24} />
            <span>❧</span>
          </div>
          <span role="status">{state.verdict ? '종결 · 읽기 전용' : noteStatus}</span>
        </div>
        <textarea
          aria-label="수사 메모"
          placeholder={
            '누가 접근할 수 있었는가?\n누가 시간에 대해 거짓말했는가?\n\n당신의 가설을 이곳에 기록하세요.'
          }
          value={notes}
          onChange={(e) => setNotes(e.target.value)}
          maxLength={20000}
          readOnly={!!state.verdict}
        />
        <div className="notebook-bottom">
          <span>{notes.length.toLocaleString()} / 20,000자 · 자동 저장</span>
          <button
            className="text-button"
            disabled={busy || !!state.verdict || notes === state.notes}
            onClick={async () => {
              const updatedState = await updateGame('notes', { text: notes });
              setNoteStatus(updatedState ? '저장됨' : '저장 실패 · 다시 시도하세요');
            }}
          >
            지금 저장 <Check size={14} />
          </button>
        </div>
      </div>
    </>
  );
}

export function ResultsScreen({ state, setModal, navigateTo }: Props) {
  const verdict = state.verdict;
  if (!verdict) return null;
  const progress = getInvestigationProgress(state);
  const review = verdict.review;
  return (
    <div className="results">
      <div className="result-seal">
        <Shield size={45} />
      </div>
      <div className="eyebrow">INVESTIGATION COMPLETE</div>
      <h1>{verdict.correct ? '진실을 밝혀냈습니다.' : '아직, 풀리지 않은 진실.'}</h1>
      <p>
        {verdict.correct
          ? '범인 검거에 필요한 핵심 입증을 완료했습니다.'
          : '증거가 말하는 이야기와 당신의 결론을 비교해 보세요.'}
      </p>
      <section className="result-progress" aria-label="수사 진행도">
        <div className="eyebrow">수사 진행도</div>
        <div className="result-progress-value">
          {progress.percent}
          <span>%</span>
        </div>
        <div
          className="progress-track"
          role="progressbar"
          aria-label="수사 진행도"
          aria-valuemin={0}
          aria-valuemax={100}
          aria-valuenow={progress.percent}
        >
          <i style={{ width: `${progress.percent}%` }} />
        </div>
        <p>수집한 자료·쟁점·추론의 완성도이며, 100%는 범인 검거 조건이 아닙니다.</p>
      </section>
      <div className="result-checks">
        {verdict.checks.map((c) => (
          <details key={c.label}>
            <summary>
              {c.correct ? <CheckCheck size={18} /> : <X size={18} />}
              <span>{c.label}</span>
              <strong>{c.correct ? '입증 완료' : '입증 실패'}</strong>
            </summary>
            <div className="result-check-detail">
              {c.label === '범인 지목' && <p>범인은 서하은입니다.</p>}
              {c.label === '범행 동기' && (
                <p>
