function DiscoveryGroup({ title, items }: { title: string; items: ReviewItem[] }) {
  const found = items.filter((item) => item.discovered);
  const missing = items.filter((item) => !item.discovered);
  return (
    <section className="discovery-group">
      <h3>{title}</h3>
