const visible = witnesses
    .filter((w) => person === 'all' || person === w.id)
    .map((w) => {
      const suspect = suspects.find((item) => item.id === w.id);
      const messages = state.messages
        .map((message, index) => ({ ...message, index }))
        .filter((m) => m.suspectId === w.id);
      // 질문과 답변을 함께 표시해 검색 시 발언의 맥락을 유지한다.
      const pairs = messages
        .filter((m) => m.role === 'user')
        .map((question) => ({
          question,
          answer: messages.find(
            (m) => m.index === question.index + 1 && m.role === 'suspect',
          ),
        }))
        .filter((pair) =>
          matches(
            w.name +
              ' ' +
              pair.question.text +
              ' ' +
              (pair.answer?.text ?? '') +
              ' ' +
              (pair.question.evidenceId ?? '') +
              ' ' +
              (state.derivedEvidence[pair.question.evidenceId ?? '']?.title ??
                evidence.find((item) => item.id === pair.question.evidenceId)?.title ??
                ''),
          ),
        );
      const initial =
        suspect && matches(w.name + ' ' + suspect.statement) ? suspect.statement : null;
      const records =
        w.id === 'butler'
          ? testimonyRecords.filter(
              (item) =>
                item.phase <= state.phase &&
                matches(w.name + ' ' + item.code + ' ' + item.title + ' ' + item.body),
            )
          : [];
      const acquired = Object.values(state.statements).filter(
        (item) =>
          item.speaker === w.id &&
          matches(w.name + ' ' + item.code + ' ' + item.title + ' ' + item.excerpt),
      );
      return { ...w, initial, pairs, records, acquired };
    })
    .filter((w) => w.initial || w.pairs.length || w.records.length || w.acquired.length);

