          >
            {w.name}
          </button>
        ))}
      </div>
      <div className="archive-groups" role="group" aria-label="증언 분류">
        {[
          ['all', '전체'],
          ['movement', '확보한 동선 진술'],
          ['relations', '다른 인물에 대한 진술'],
